// Initialize data integrity test configuration
const integrityConfig = {
  testId: 'integrity_' + Date.now(),
  startTime: new Date().toISOString(),
  testSuite: 'data_integrity',
  testScope: {
    databases: ['characters', 'memories', 'sessions', 'campaigns', 'quests'],
    dataTypes: ['character_state', 'memory_data', 'session_state', 'campaign_progress', 'quest_status'],
    consistencyChecks: ['referential_integrity', 'data_validation', 'transaction_integrity', 'backup_integrity']
  },
  corruptionDetection: {
    enableChecksums: true,
    enableDataValidation: true,
    enableSchemaValidation: true,
    testScenarios: ['data_corruption', 'partial_updates', 'concurrent_modifications', 'rollback_scenarios']
  },
  validationRules: {
    characterState: {
      requiredFields: ['id', 'name', 'class', 'level', 'abilities'],
      dataTypes: {
        level: 'number',
        experience: 'number',
        abilities: 'object'
      },
      valueConstraints: {
        level: { min: 1, max: 20 },
        abilities: { min: 1, max: 20 }
      }
    },
    memoryData: {
      requiredFields: ['id', 'character_id', 'memory_type', 'content', 'timestamp'],
      dataTypes: {
        timestamp: 'date',
        importance_score: 'number'
      },
      relationships: {
        character_id: 'characters.id'
      }
    }
  }
};

$items[0].json.integrityConfig = integrityConfig;

return [{
  json: {
    ...integrityConfig,
    status: 'initialized',
    currentTest: 'character_state_consistency'
  }
}];

// Analyze data integrity test results and generate comprehensive report
const integrityResults = {
  testId: $json.testId,
  testSuite: 'data_integrity',
  startTime: $json.startTime,
  endTime: new Date().toISOString(),
  totalDuration: Date.now() - new Date($json.startTime).getTime(),
  tests: [
    {
      name: 'character_state_consistency',
      status: $json.characterStateResults ? 'passed' : 'failed',
      recordsValidated: $json.characterStateValidated || 0,
      violationsFound: $json.characterStateViolations || 0,
      corruptionDetected: $json.characterStateCorruption || false,
      consistencyScore: $json.characterStateConsistencyScore || 0,
      details: $json.characterStateDetails || {}
    },
    {
      name: 'memory_corruption_detection',
      status: $json.memoryCorruptionResults ? 'passed' : 'failed',
      memoriesChecked: $json.memoriesChecked || 0,
      corruptionInstances: $json.memoryCorruptionInstances || 0,
      checksumValidations: $json.memoryChecksumValidations || 0,
      integrityScore: $json.memoryIntegrityScore || 0,
      details: $json.memoryCorruptionDetails || {}
    },
    {
      name: 'transaction_rollback',
      status: $json.transactionRollbackResults ? 'passed' : 'failed',
      transactionsTested: $json.transactionsTested || 0,
      rollbacksValidated: $json.rollbacksValidated || 0,
      rollbackFailures: $json.rollbackFailures || 0,
      dataIntegrityMaintained: $json.rollbackDataIntegrity || false,
      details: $json.transactionRollbackDetails || {}
    },
    {
      name: 'cross_service_synchronization',
      status: $json.crossServiceSyncResults ? 'passed' : 'failed',
      servicesTested: $json.servicesTested || 0,
      syncOperations: $json.syncOperations || 0,
      syncFailures: $json.syncFailures || 0,
      consistencyIssues: $json.syncConsistencyIssues || 0,
      details: $json.crossServiceSyncDetails || {}
    },
    {
      name: 'backup_restore_verification',
      status: $json.backupRestoreResults ? 'passed' : 'failed',
      backupsCreated: $json.backupsCreated || 0,
      restoresPerformed: $json.restoresPerformed || 0,
      backupCorruptionDetected: $json.backupCorruptionDetected || 0,
      restoreValidationPassed: $json.restoreValidationPassed || 0,
      details: $json.backupRestoreDetails || {}
    },
    {
      name: 'concurrent_modifications',
      status: $json.concurrentModResults ? 'passed' : 'failed',
      concurrentOperations: $json.concurrentOperations || 0,
      conflictsDetected: $json.conflictsDetected || 0,
      dataLossIncidents: $json.dataLossIncidents || 0,
      isolationViolations: $json.isolationViolations || 0,
      details: $json.concurrentModificationsDetails || {}
    },
    {
      name: 'schema_validation',
      status: $json.schemaValidationResults ? 'passed' : 'failed',
      schemasValidated: $json.schemasValidated || 0,
      validationErrors: $json.schemaValidationErrors || 0,
      constraintViolations: $json.constraintViolations || 0,
      migrationTestsPassed: $json.migrationTestsPassed || 0,
      details: $json.schemaValidationDetails || {}
    },
    {
      name: 'data_recovery',
      status: $json.dataRecoveryResults ? 'passed' : 'failed',
      recoveryScenarios: $json.recoveryScenarios || 0,
      successfulRecoveries: $json.successfulRecoveries || 0,
      dataLossEvents: $json.dataLossEvents || 0,
      recoveryTimeAverage: $json.recoveryTimeAverage || 0,
      details: $json.dataRecoveryDetails || {}
    }
  ],
  overallMetrics: {
    totalRecordsValidated: $json.totalRecordsValidated || 0,
    totalViolations: $json.totalViolations || 0,
    totalCorruptionInstances: $json.totalCorruptionInstances || 0,
    averageConsistencyScore: 0
  }
};

// Calculate integrity summary
const passedTests = integrityResults.tests.filter(t => t.status === 'passed').length;
const totalTests = integrityResults.tests.length;
const successRate = (passedTests / totalTests * 100).toFixed(1);

// Calculate overall consistency score
const consistencyScores = integrityResults.tests.map(t => t.consistencyScore || t.integrityScore || 0).filter(s => s > 0);
integrityResults.overallMetrics.averageConsistencyScore = 
  consistencyScores.length > 0 ? consistencyScores.reduce((sum, score) => sum + score, 0) / consistencyScores.length : 0;

// Determine overall integrity rating
let integrityRating = 'excellent';
if (integrityResults.overallMetrics.totalViolations > 0) {
  integrityRating = 'poor';
} else if (integrityResults.overallMetrics.totalCorruptionInstances > 0) {
  integrityRating = 'fair';
} else if (integrityResults.overallMetrics.averageConsistencyScore < 95) {
  integrityRating = 'good';
}

// Critical issues detection
const criticalIssues = [];
if (integrityResults.overallMetrics.totalCorruptionInstances > 0) {
  criticalIssues.push('Data corruption detected');
}
if (integrityResults.tests.find(t => t.dataLossIncidents > 0)) {
  criticalIssues.push('Data loss incidents detected');
}
if (integrityResults.tests.find(t => t.rollbackFailures > 0)) {
  criticalIssues.push('Transaction rollback failures');
}

const summary = {
  totalTests,
  passedTests,
  failedTests: totalTests - passedTests,
  successRate: parseFloat(successRate),
  overallStatus: criticalIssues.length > 0 ? 'failed' : successRate >= 90 ? 'passed' : 'warning',
  integrityRating,
  criticalIssues,
  overallMetrics: integrityResults.overallMetrics
};

return [{
  json: {
    testSuite: 'data_integrity',
    ...integrityResults,
    summary,
    status: summary.overallStatus,
    timestamp: new Date().toISOString()
  }
}];

// Generate data integrity recommendations and alerts
const recommendations = [];
const alerts = [];

// Analyze test results for recommendations
$json.tests.forEach(test => {
  if (test.violationsFound > 0) {
    recommendations.push({
      category: 'data_validation',
      priority: 'high',
      test: test.name,
      issue: `${test.violationsFound} data validation violations found`,
      suggestion: 'Review and fix data validation rules, implement stricter input validation'
    });
  }

  if (test.corruptionDetected) {
    alerts.push({
      level: 'critical',
      category: 'data_corruption',
      test: test.name,
      message: 'Data corruption detected - immediate investigation required',
      action: 'Isolate affected systems and perform data restoration'
    });
  }

  if (test.consistencyScore < 95 && test.consistencyScore > 0) {
    recommendations.push({
      category: 'consistency',
      priority: 'medium',
      test: test.name,
      issue: `Consistency score of ${test.consistencyScore}% below threshold`,
      suggestion: 'Review synchronization mechanisms and improve consistency checks'
    });
  }
});

// Check for critical integrity issues
if ($json.summary.criticalIssues.length > 0) {
  alerts.push({
    level: 'critical',
    category: 'system_integrity',
    message: `Critical integrity issues detected: ${$json.summary.criticalIssues.join(', ')}`,
    action: 'Immediate system maintenance and data integrity restoration required'
  });
}

// Performance recommendations
if ($json.overallMetrics.totalRecordsValidated > 0 && 
    $json.overallMetrics.totalViolations / $json.overallMetrics.totalRecordsValidated > 0.01) {
  recommendations.push({
    category: 'data_quality',
    priority: 'high',
    issue: 'Data quality issues exceed 1% threshold',
    suggestion: 'Implement comprehensive data quality monitoring and automated correction'
  });
}

// Backup and recovery recommendations
const backupTest = $json.tests.find(t => t.name === 'backup_restore_verification');
if (backupTest && backupTest.backupCorruptionDetected > 0) {
  recommendations.push({
    category: 'backup_system',
    priority: 'critical',
    issue: 'Backup corruption detected',
    suggestion: 'Review backup procedures, implement backup verification, and consider alternative backup strategies'
  });
}

// Transaction integrity recommendations
const transactionTest = $json.tests.find(t => t.name === 'transaction_rollback');
if (transactionTest && transactionTest.rollbackFailures > 0) {
  recommendations.push({
    category: 'transaction_management',
    priority: 'high',
    issue: 'Transaction rollback failures detected',
    suggestion: 'Review transaction management, improve error handling, and test rollback procedures'
  });
}

return [{
  json: {
    testId: $json.testId,
    recommendations,
    alerts,
    summary: {
      totalRecommendations: recommendations.length,
      criticalAlerts: alerts.filter(a => a.level === 'critical').length,
      highPriorityIssues: recommendations.filter(r => r.priority === 'high').length,
      mediumPriorityIssues: recommendations.filter(r => r.priority === 'medium').length
    },
    timestamp: new Date().toISOString()
  }
}];
